  "Browser.removeAllListeners": {"key":"Browser.removeAllListeners","title":"browser.removeAllListeners()","signature":"removeAllListeners(type?: string): this","returns":"this","since":"v1.47","docsUrl":"https://playwright.dev/docs/api/class-browser#browser-remove-all-listeners","params":[{"name":"type","type":"string","required":false,"description":""}],"options":[{"name":"behavior","type":"RemoveAllListenersBehavior<\"wait\"|\"ignoreErrors\"|\"default\">","required":false,"description":"Specifies whether to wait for already running listeners and what to do if they throw errors:\n* `'default'` - do not wait for current listener calls (if any) to finish, if the listener throws, it may result in unhandled error\n* `'wait'` - wait for current listener calls (if any) to finish\n* `'ignoreErrors'` - do not wait for current listener calls (if any) to finish, all errors thrown by the listeners after removal are silently caught"}]},
