  "Frame.dragAndDrop": {"key":"Frame.dragAndDrop","title":"frame.dragAndDrop()","signature":"dragAndDrop(source: string, target: string, options?: Object): Promise<void>","returns":"Promise<void>","since":"v1.13","docsUrl":"https://playwright.dev/docs/api/class-frame#frame-drag-and-drop","params":[{"name":"source","type":"string","required":true,"description":"A selector to search for an element to drag. If there are multiple elements satisfying the selector, the first will be used."},{"name":"target","type":"string","required":true,"description":"A selector to search for an element to drop onto. If there are multiple elements satisfying the selector, the first will be used."},{"name":"options","type":"Object","required":false,"description":""}],"options":[{"name":"force","type":"boolean","required":false,"description":"Whether to bypass the actionability checks. Defaults to `false`.","default":"false"},{"name":"scroll","type":"ScrollMode<\"auto\"|\"none\">","required":false,"description":"Controls whether Playwright scrolls the element into view before performing the action. Defaults to `\"auto\"`,\nwhich scrolls the element into view when necessary, including scrolling nested scrollable containers. When set to\n`\"none\"`, Playwright does not scroll the element and the action fails if the element is not already in the viewport.\nThis is useful to assert that an element is reachable by the user without additional scrolling.","default":"\"auto\""},{"name":"noWaitAfter","type":"boolean","required":false,"description":"This option has no effect."},{"name":"strict","type":"boolean","required":false,"description":"When true, the call requires selector to resolve to a single element. If given selector resolves to more\nthan one element, the call throws an exception."},{"name":"timeout","type":"float","required":false,"description":"Maximum time in milliseconds. Defaults to `0` - no timeout. The default value can be changed via `actionTimeout` option in the config, or by using the `BrowserContext.setDefaultTimeout()` or\n`Page.setDefaultTimeout()` methods.","default":"0"},{"name":"signal","type":"AbortSignal","required":false,"description":"Allows to cancel the operation using an `AbortSignal`. If the signal is aborted, the operation will be aborted and throw an error.\nNote that providing a signal does not disable the default timeout, which can be changed using `BrowserContext.setDefaultTimeout()` or `Page.setDefaultTimeout()`; pass `timeout: 0` to disable the timeout entirely."},{"name":"trial","type":"boolean","required":false,"description":"When set, this method only performs the actionability checks and skips the action. Defaults to `false`. Useful to wait until the element is ready for the action without performing it.","default":"false"},{"name":"sourcePosition","type":"Object","required":false,"description":"* alias-java: Position\n  - `x` <[float]>\n  - `y` <[float]>\n\nClicks on the source element at this point relative to the top-left corner of the element's padding box. If not specified, some visible point of the element is used."},{"name":"targetPosition","type":"Object","required":false,"description":"* alias-java: Position\n  - `x` <[float]>\n  - `y` <[float]>\n\nDrops on the target element at this point relative to the top-left corner of the element's padding box. If not specified, some visible point of the element is used."},{"name":"steps","type":"int","required":false,"description":"Defaults to 1. Sends `n` interpolated `mousemove` events to represent travel between the `mousedown` and `mouseup` of the drag. When set to 1, emits a single `mousemove` event at the destination location.","default":"1"}]},
  "Frame.evalOnSelector": {"key":"Frame.evalOnSelector","title":"frame.evalOnSelector()","signature":"evalOnSelector(): void","since":"v1.9","docsUrl":"https://playwright.dev/docs/api/class-frame#frame-eval-on-selector","params":[{"name":"selector","type":"string","required":true,"description":"A selector to query for."},{"name":"expression","type":"string","required":true,"description":"JavaScript expression to be evaluated in the browser context. If the expression evaluates\nto a function, the function is automatically invoked."},{"name":"pageFunction","type":"function\\(Element\\)|string","required":true,"description":"Function to be evaluated in the page context."},{"name":"arg","type":"unknown","required":true,"description":"Optional argument to pass to `expression`."}],"options":[{"name":"strict","type":"boolean","required":false,"description":"When true, the call requires selector to resolve to a single element. If given selector resolves to more\nthan one element, the call throws an exception."}]},
