  "Frame.goto": {"key":"Frame.goto","title":"frame.goto()","signature":"goto(url: string, options?: Object): Promise<null|Response>","returns":"Promise<null|Response>","since":"v1.8","docsUrl":"https://playwright.dev/docs/api/class-frame#frame-goto","params":[{"name":"url","type":"string","required":true,"description":"URL to navigate frame to. The url should include scheme, e.g. `https://`."},{"name":"options","type":"Object","required":false,"description":""}],"options":[{"name":"waitUntil","type":"WaitUntilState<\"load\"|\"domcontentloaded\"|\"networkidle\"|\"commit\">","required":false,"description":"When to consider operation succeeded, defaults to `load`. Events can be either:\n* `'domcontentloaded'` - consider operation to be finished when the `DOMContentLoaded` event is fired.\n* `'load'` - consider operation to be finished when the `load` event is fired.\n* `'networkidle'` - **DISCOURAGED** consider operation to be finished when there are no network connections for at least `500` ms. Don't use this method for testing, rely on web assertions to assess readiness instead.\n* `'commit'` - consider operation to be finished when network response is received and the document started loading.","default":"load"},{"name":"timeout","type":"float","required":false,"description":"Maximum operation time in milliseconds. Defaults to `0` - no timeout. The default value can be changed via `navigationTimeout` option in the config, or by using the `BrowserContext.setDefaultNavigationTimeout()`,\n`BrowserContext.setDefaultTimeout()`,\n`Page.setDefaultNavigationTimeout()` or\n`Page.setDefaultTimeout()` methods.","default":"0"},{"name":"signal","type":"AbortSignal","required":false,"description":"Allows to cancel the operation using an `AbortSignal`. If the signal is aborted, the operation will be aborted and throw an error.\nNote that providing a signal does not disable the default timeout, which can be changed using `BrowserContext.setDefaultTimeout()` or `Page.setDefaultTimeout()`; pass `timeout: 0` to disable the timeout entirely."},{"name":"referer","type":"string","required":false,"description":"Referer header value. If provided it will take preference over the referer header value set by\n`Page.setExtraHTTPHeaders()`."}]},
  "Frame.hover": {"key":"Frame.hover","title":"frame.hover()","signature":"hover(selector: string, options?: Object): Promise<void>","returns":"Promise<void>","since":"v1.8","docsUrl":"https://playwright.dev/docs/api/class-frame#frame-hover","params":[{"name":"selector","type":"string","required":true,"description":"A selector to search for an element. If there are multiple elements satisfying the selector, the first will be used."},{"name":"options","type":"Object","required":false,"description":""}],"options":[{"name":"position","type":"Object","required":false,"description":"* alias: Position\n  - `x` <[float]>\n  - `y` <[float]>\n\nA point to use relative to the top-left corner of element padding box. If not specified, uses some visible point of the\nelement."},{"name":"modifiers","type":"Array<KeyboardModifier<\"Alt\"|\"Control\"|\"ControlOrMeta\"|\"Meta\"|\"Shift\">>","required":false,"description":"Modifier keys to press. Ensures that only these modifiers are pressed during the operation, and then restores current\nmodifiers back. If not specified, currently pressed modifiers are used. \"ControlOrMeta\" resolves to \"Control\" on Windows\nand Linux and to \"Meta\" on macOS."},{"name":"force","type":"boolean","required":false,"description":"Whether to bypass the actionability checks. Defaults to `false`.","default":"false"},{"name":"scroll","type":"ScrollMode<\"auto\"|\"none\">","required":false,"description":"Controls whether Playwright scrolls the element into view before performing the action. Defaults to `\"auto\"`,\nwhich scrolls the element into view when necessary, including scrolling nested scrollable containers. When set to\n`\"none\"`, Playwright does not scroll the element and the action fails if the element is not already in the viewport.\nThis is useful to assert that an element is reachable by the user without additional scrolling.","default":"\"auto\""},{"name":"strict","type":"boolean","required":false,"description":"When true, the call requires selector to resolve to a single element. If given selector resolves to more\nthan one element, the call throws an exception."},{"name":"timeout","type":"float","required":false,"description":"Maximum time in milliseconds. Defaults to `0` - no timeout. The default value can be changed via `actionTimeout` option in the config, or by using the `BrowserContext.setDefaultTimeout()` or\n`Page.setDefaultTimeout()` methods.","default":"0"},{"name":"signal","type":"AbortSignal","required":false,"description":"Allows to cancel the operation using an `AbortSignal`. If the signal is aborted, the operation will be aborted and throw an error.\nNote that providing a signal does not disable the default timeout, which can be changed using `BrowserContext.setDefaultTimeout()` or `Page.setDefaultTimeout()`; pass `timeout: 0` to disable the timeout entirely."},{"name":"trial","type":"boolean","required":false,"description":"When set, this method only performs the actionability checks and skips the action. Defaults to `false`. Useful to wait until the element is ready for the action without performing it. Note that keyboard `modifiers` will be pressed regardless of `trial` to allow testing elements which are only visible when those keys are pressed.","default":"false"},{"name":"noWaitAfter","type":"boolean","required":false,"description":"This option has no effect."}]},
