  "Frame.locator": {"key":"Frame.locator","title":"frame.locator()","signature":"locator(selector: string, options?: Object): Locator","returns":"Locator","since":"v1.14","docsUrl":"https://playwright.dev/docs/api/class-frame#frame-locator","params":[{"name":"selector","type":"string","required":true,"description":"A selector to use when resolving DOM element."},{"name":"options","type":"Object","required":false,"description":""}],"options":[{"name":"hasNot","type":"Locator","required":false,"description":"Matches elements that do not contain an element that matches an inner locator. Inner locator is queried against the outer one.\nFor example, `article` that does not have `div` matches `<article><span>Playwright</span></article>`.\n\nNote that outer and inner locators must belong to the same frame. Inner locator must not contain [FrameLocator]s."},{"name":"hasNotText","type":"string|RegExp","required":false,"description":"Matches elements that do not contain specified text somewhere inside, possibly in a child or a descendant element. When passed a [string], matching is case-insensitive and searches for a substring."}]},
