  "Frame.selectOption": {"key":"Frame.selectOption","title":"frame.selectOption()","signature":"selectOption(selector: string, values: null|string|ElementHandle|ReadonlyArray<string>|{ /** * Mat…, options?: Object): Promise<Array<string>>","returns":"Promise<Array<string>>","since":"v1.8","docsUrl":"https://playwright.dev/docs/api/class-frame#frame-select-option","params":[{"name":"selector","type":"string","required":true,"description":"A selector to query for."},{"name":"values","type":"null|string|ElementHandle|ReadonlyArray<string>|{ /** * Matches by `option.value`. Optional. */ value?: string; /** * M…","required":true,"description":"* alias-java: SelectOption\n  - `value` ?<[string]> Matches by `option.value`. Optional.\n  - `label` ?<[string]> Matches by `option.label`. Optional.\n  - `index` ?<[int]> Matches by the index. Optional.\n\nOptions to select. If the `<select>` has the `multiple` attribute, all matching options are selected, otherwise only the\nfirst option matching one of the passed options is selected. String values are matching both values and labels. Option\nis considered matching if all specified properties match."},{"name":"options","type":"Object","required":false,"description":""}],"options":[{"name":"force","type":"boolean","required":false,"description":"Whether to bypass the actionability checks. Defaults to `false`.","default":"false"},{"name":"noWaitAfter","type":"boolean","required":false,"description":"This option has no effect."},{"name":"strict","type":"boolean","required":false,"description":"When true, the call requires selector to resolve to a single element. If given selector resolves to more\nthan one element, the call throws an exception."},{"name":"timeout","type":"float","required":false,"description":"Maximum time in milliseconds. Defaults to `0` - no timeout. The default value can be changed via `actionTimeout` option in the config, or by using the `BrowserContext.setDefaultTimeout()` or\n`Page.setDefaultTimeout()` methods.","default":"0"},{"name":"signal","type":"AbortSignal","required":false,"description":"Allows to cancel the operation using an `AbortSignal`. If the signal is aborted, the operation will be aborted and throw an error.\nNote that providing a signal does not disable the default timeout, which can be changed using `BrowserContext.setDefaultTimeout()` or `Page.setDefaultTimeout()`; pass `timeout: 0` to disable the timeout entirely."}]},
  "Frame.setChecked": {"key":"Frame.setChecked","title":"frame.setChecked()","signature":"setChecked(selector: string, checked: boolean, options?: Object): Promise<void>","returns":"Promise<void>","since":"v1.15","docsUrl":"https://playwright.dev/docs/api/class-frame#frame-set-checked","params":[{"name":"selector","type":"string","required":true,"description":"A selector to search for an element. If there are multiple elements satisfying the selector, the first will be used."},{"name":"checked","type":"boolean","required":true,"description":"Whether to check or uncheck the checkbox."},{"name":"options","type":"Object","required":false,"description":""}],"options":[{"name":"force","type":"boolean","required":false,"description":"Whether to bypass the actionability checks. Defaults to `false`.","default":"false"},{"name":"scroll","type":"ScrollMode<\"auto\"|\"none\">","required":false,"description":"Controls whether Playwright scrolls the element into view before performing the action. Defaults to `\"auto\"`,\nwhich scrolls the element into view when necessary, including scrolling nested scrollable containers. When set to\n`\"none\"`, Playwright does not scroll the element and the action fails if the element is not already in the viewport.\nThis is useful to assert that an element is reachable by the user without additional scrolling.","default":"\"auto\""},{"name":"noWaitAfter","type":"boolean","required":false,"description":"This option has no effect."},{"name":"position","type":"Object","required":false,"description":"* alias: Position\n  - `x` <[float]>\n  - `y` <[float]>\n\nA point to use relative to the top-left corner of element padding box. If not specified, uses some visible point of the\nelement."},{"name":"strict","type":"boolean","required":false,"description":"When true, the call requires selector to resolve to a single element. If given selector resolves to more\nthan one element, the call throws an exception."},{"name":"timeout","type":"float","required":false,"description":"Maximum time in milliseconds. Defaults to `0` - no timeout. The default value can be changed via `actionTimeout` option in the config, or by using the `BrowserContext.setDefaultTimeout()` or\n`Page.setDefaultTimeout()` methods.","default":"0"},{"name":"signal","type":"AbortSignal","required":false,"description":"Allows to cancel the operation using an `AbortSignal`. If the signal is aborted, the operation will be aborted and throw an error.\nNote that providing a signal does not disable the default timeout, which can be changed using `BrowserContext.setDefaultTimeout()` or `Page.setDefaultTimeout()`; pass `timeout: 0` to disable the timeout entirely."},{"name":"trial","type":"boolean","required":false,"description":"When set, this method only performs the actionability checks and skips the action. Defaults to `false`. Useful to wait until the element is ready for the action without performing it.","default":"false"}]},
  "Frame.setContent": {"key":"Frame.setContent","title":"frame.setContent()","signature":"setContent(html: string, options?: Object): Promise<void>","returns":"Promise<void>","since":"v1.8","docsUrl":"https://playwright.dev/docs/api/class-frame#frame-set-content","params":[{"name":"html","type":"string","required":true,"description":"HTML markup to assign to the page."},{"name":"options","type":"Object","required":false,"description":""}],"options":[{"name":"timeout","type":"float","required":false,"description":"Maximum operation time in milliseconds. Defaults to `0` - no timeout. The default value can be changed via `navigationTimeout` option in the config, or by using the `BrowserContext.setDefaultNavigationTimeout()`,\n`BrowserContext.setDefaultTimeout()`,\n`Page.setDefaultNavigationTimeout()` or\n`Page.setDefaultTimeout()` methods.","default":"0"},{"name":"signal","type":"AbortSignal","required":false,"description":"Allows to cancel the operation using an `AbortSignal`. If the signal is aborted, the operation will be aborted and throw an error.\nNote that providing a signal does not disable the default timeout, which can be changed using `BrowserContext.setDefaultTimeout()` or `Page.setDefaultTimeout()`; pass `timeout: 0` to disable the timeout entirely."},{"name":"waitUntil","type":"WaitUntilState<\"load\"|\"domcontentloaded\"|\"networkidle\"|\"commit\">","required":false,"description":"When to consider operation succeeded, defaults to `load`. Events can be either:\n* `'domcontentloaded'` - consider operation to be finished when the `DOMContentLoaded` event is fired.\n* `'load'` - consider operation to be finished when the `load` event is fired.\n* `'networkidle'` - **DISCOURAGED** consider operation to be finished when there are no network connections for at least `500` ms. Don't use this method for testing, rely on web assertions to assess readiness instead.\n* `'commit'` - consider operation to be finished when network response is received and the document started loading.","default":"load"}]},
