  "Frame.waitForNavigation": {"key":"Frame.waitForNavigation","title":"frame.waitForNavigation()","signature":"waitForNavigation(options?: Object): Promise<null|Response>","returns":"Promise<null|Response>","since":"v1.8","docsUrl":"https://playwright.dev/docs/api/class-frame#frame-wait-for-navigation","deprecated":"This method is inherently racy, please use\n[frame.waitForURL(url[, options])](https://playwright.dev/docs/api/class-frame#frame-wait-for-url) instead.","params":[{"name":"options","type":"Object","required":false,"description":""}],"options":[{"name":"url","type":"string|RegExp|URLPattern|function\\(URL\\):boolean","required":false,"description":"A glob pattern, regex pattern, URL pattern, or predicate receiving [URL] to match while waiting for the navigation. Note that if\nthe parameter is a string without wildcard characters, the method will wait for navigation to URL that is exactly\nequal to the string."},{"name":"waitUntil","type":"WaitUntilState<\"load\"|\"domcontentloaded\"|\"networkidle\"|\"commit\">","required":false,"description":"When to consider operation succeeded, defaults to `load`. Events can be either:\n* `'domcontentloaded'` - consider operation to be finished when the `DOMContentLoaded` event is fired.\n* `'load'` - consider operation to be finished when the `load` event is fired.\n* `'networkidle'` - **DISCOURAGED** consider operation to be finished when there are no network connections for at least `500` ms. Don't use this method for testing, rely on web assertions to assess readiness instead.\n* `'commit'` - consider operation to be finished when network response is received and the document started loading.","default":"load"},{"name":"timeout","type":"float","required":false,"description":"Maximum operation time in milliseconds. Defaults to `0` - no timeout. The default value can be changed via `navigationTimeout` option in the config, or by using the `BrowserContext.setDefaultNavigationTimeout()`,\n`BrowserContext.setDefaultTimeout()`,\n`Page.setDefaultNavigationTimeout()` or\n`Page.setDefaultTimeout()` methods.","default":"0"},{"name":"signal","type":"AbortSignal","required":false,"description":"Allows to cancel the waiting using an `AbortSignal`. If the signal is aborted, the waiting will be aborted and the operation will throw an error.\nNote that providing a signal does not disable the default timeout, which can be changed using `BrowserContext.setDefaultTimeout()`; pass `timeout: 0` to disable the timeout entirely."}]},
  "Frame.waitForSelector": {"key":"Frame.waitForSelector","title":"frame.waitForSelector()","signature":"waitForSelector(selector: K, options?: PageWaitForSelectorOptionsNotHidden): Promise<ElementHandleForTag<K>>","returns":"Promise<ElementHandleForTag<K>>","since":"v1.8","docsUrl":"https://playwright.dev/docs/api/class-frame#frame-wait-for-selector","params":[{"name":"selector","type":"K","required":true,"description":"A selector to query for."},{"name":"options","type":"PageWaitForSelectorOptionsNotHidden","required":false,"description":""}],"options":[{"name":"state","type":"WaitForSelectorState<\"attached\"|\"detached\"|\"visible\"|\"hidden\">","required":false,"description":"Defaults to `'visible'`. Can be either:\n* `'attached'` - wait for element to be present in DOM.\n* `'detached'` - wait for element to not be present in DOM.\n* `'visible'` - wait for element to have non-empty bounding box and no `visibility:hidden`. Note that element without\n  any content or with `display:none` has an empty bounding box and is not considered visible.\n* `'hidden'` - wait for element to be either detached from DOM, or have an empty bounding box or `visibility:hidden`.\n  This is opposite to the `'visible'` option.","default":"'visible'"},{"name":"strict","type":"boolean","required":false,"description":"When true, the call requires selector to resolve to a single element. If given selector resolves to more\nthan one element, the call throws an exception."},{"name":"timeout","type":"float","required":false,"description":"Maximum time in milliseconds. Defaults to `0` - no timeout. The default value can be changed via `actionTimeout` option in the config, or by using the `BrowserContext.setDefaultTimeout()` or\n`Page.setDefaultTimeout()` methods.","default":"0"},{"name":"signal","type":"AbortSignal","required":false,"description":"Allows to cancel the operation using an `AbortSignal`. If the signal is aborted, the operation will be aborted and throw an error.\nNote that providing a signal does not disable the default timeout, which can be changed using `BrowserContext.setDefaultTimeout()` or `Page.setDefaultTimeout()`; pass `timeout: 0` to disable the timeout entirely."}]},
  "Frame.waitForTimeout": {"key":"Frame.waitForTimeout","title":"frame.waitForTimeout()","signature":"waitForTimeout(timeout: number): Promise<void>","returns":"Promise<void>","since":"v1.8","docsUrl":"https://playwright.dev/docs/api/class-frame#frame-wait-for-timeout","params":[{"name":"timeout","type":"number","required":true,"description":"A timeout to wait for"}],"options":[]},
  "Frame.waitForURL": {"key":"Frame.waitForURL","title":"frame.waitForURL()","signature":"waitForURL(url: string|RegExp|URLPattern|((url: URL) => boolean), options?: Object): Promise<void>","returns":"Promise<void>","since":"v1.11","docsUrl":"https://playwright.dev/docs/api/class-frame#frame-wait-for-url","params":[{"name":"url","type":"string|RegExp|URLPattern|((url: URL) => boolean)","required":true,"description":"A glob pattern, regex pattern, URL pattern, or predicate receiving [URL] to match while waiting for the navigation. Note that if\nthe parameter is a string without wildcard characters, the method will wait for navigation to URL that is exactly\nequal to the string."},{"name":"options","type":"Object","required":false,"description":""}],"options":[{"name":"timeout","type":"float","required":false,"description":"Maximum operation time in milliseconds. Defaults to `0` - no timeout. The default value can be changed via `navigationTimeout` option in the config, or by using the `BrowserContext.setDefaultNavigationTimeout()`,\n`BrowserContext.setDefaultTimeout()`,\n`Page.setDefaultNavigationTimeout()` or\n`Page.setDefaultTimeout()` methods.","default":"0"},{"name":"signal","type":"AbortSignal","required":false,"description":"Allows to cancel the waiting using an `AbortSignal`. If the signal is aborted, the waiting will be aborted and the operation will throw an error.\nNote that providing a signal does not disable the default timeout, which can be changed using `BrowserContext.setDefaultTimeout()`; pass `timeout: 0` to disable the timeout entirely."},{"name":"waitUntil","type":"WaitUntilState<\"load\"|\"domcontentloaded\"|\"networkidle\"|\"commit\">","required":false,"description":"When to consider operation succeeded, defaults to `load`. Events can be either:\n* `'domcontentloaded'` - consider operation to be finished when the `DOMContentLoaded` event is fired.\n* `'load'` - consider operation to be finished when the `load` event is fired.\n* `'networkidle'` - **DISCOURAGED** consider operation to be finished when there are no network connections for at least `500` ms. Don't use this method for testing, rely on web assertions to assess readiness instead.\n* `'commit'` - consider operation to be finished when network response is received and the document started loading.","default":"load"}]},
