  "Locator.check": {"key":"Locator.check","title":"locator.check()","signature":"check(options?: Object): Promise<void>","returns":"Promise<void>","since":"v1.14","docsUrl":"https://playwright.dev/docs/api/class-locator#locator-check","params":[{"name":"options","type":"Object","required":false,"description":""}],"options":[{"name":"position","type":"Object","required":false,"description":"* alias: Position\n  - `x` <[float]>\n  - `y` <[float]>\n\nA point to use relative to the top-left corner of element padding box. If not specified, uses some visible point of the\nelement."},{"name":"force","type":"boolean","required":false,"description":"Whether to bypass the actionability checks. Defaults to `false`.","default":"false"},{"name":"scroll","type":"ScrollMode<\"auto\"|\"none\">","required":false,"description":"Controls whether Playwright scrolls the element into view before performing the action. Defaults to `\"auto\"`,\nwhich scrolls the element into view when necessary, including scrolling nested scrollable containers. When set to\n`\"none\"`, Playwright does not scroll the element and the action fails if the element is not already in the viewport.\nThis is useful to assert that an element is reachable by the user without additional scrolling.","default":"\"auto\""},{"name":"noWaitAfter","type":"boolean","required":false,"description":"This option has no effect."},{"name":"timeout","type":"float","required":false,"description":"Maximum time in milliseconds. Defaults to `0` - no timeout. The default value can be changed via `actionTimeout` option in the config, or by using the `BrowserContext.setDefaultTimeout()` or\n`Page.setDefaultTimeout()` methods.","default":"0"},{"name":"signal","type":"AbortSignal","required":false,"description":"Allows to cancel the operation using an `AbortSignal`. If the signal is aborted, the operation will be aborted and throw an error.\nNote that providing a signal does not disable the default timeout, which can be changed using `BrowserContext.setDefaultTimeout()` or `Page.setDefaultTimeout()`; pass `timeout: 0` to disable the timeout entirely."},{"name":"trial","type":"boolean","required":false,"description":"When set, this method only performs the actionability checks and skips the action. Defaults to `false`. Useful to wait until the element is ready for the action without performing it.","default":"false"}]},
  "Locator.clear": {"key":"Locator.clear","title":"locator.clear()","signature":"clear(options?: Object): Promise<void>","returns":"Promise<void>","since":"v1.28","docsUrl":"https://playwright.dev/docs/api/class-locator#locator-clear","params":[{"name":"options","type":"Object","required":false,"description":""}],"options":[{"name":"force","type":"boolean","required":false,"description":"Whether to bypass the actionability checks. Defaults to `false`.","default":"false"},{"name":"noWaitAfter","type":"boolean","required":false,"description":"This option has no effect."},{"name":"timeout","type":"float","required":false,"description":"Maximum time in milliseconds. Defaults to `0` - no timeout. The default value can be changed via `actionTimeout` option in the config, or by using the `BrowserContext.setDefaultTimeout()` or\n`Page.setDefaultTimeout()` methods.","default":"0"},{"name":"signal","type":"AbortSignal","required":false,"description":"Allows to cancel the operation using an `AbortSignal`. If the signal is aborted, the operation will be aborted and throw an error.\nNote that providing a signal does not disable the default timeout, which can be changed using `BrowserContext.setDefaultTimeout()` or `Page.setDefaultTimeout()`; pass `timeout: 0` to disable the timeout entirely."}]},
  "Locator.click": {"key":"Locator.click","title":"locator.click()","signature":"click(options?: Object): Promise<void>","returns":"Promise<void>","since":"v1.14","docsUrl":"https://playwright.dev/docs/api/class-locator#locator-click","params":[{"name":"options","type":"Object","required":false,"description":""}],"options":[{"name":"button","type":"MouseButton<\"left\"|\"right\"|\"middle\">","required":false,"description":"Defaults to `left`.","default":"left"},{"name":"clickCount","type":"int","required":false,"description":"defaults to 1. See [UIEvent.detail].","default":"1"},{"name":"delay","type":"float","required":false,"description":"Time to wait between `mousedown` and `mouseup` in milliseconds. Defaults to 0.","default":"0"},{"name":"position","type":"Object","required":false,"description":"* alias: Position\n  - `x` <[float]>\n  - `y` <[float]>\n\nA point to use relative to the top-left corner of element padding box. If not specified, uses some visible point of the\nelement."},{"name":"modifiers","type":"Array<KeyboardModifier<\"Alt\"|\"Control\"|\"ControlOrMeta\"|\"Meta\"|\"Shift\">>","required":false,"description":"Modifier keys to press. Ensures that only these modifiers are pressed during the operation, and then restores current\nmodifiers back. If not specified, currently pressed modifiers are used. \"ControlOrMeta\" resolves to \"Control\" on Windows\nand Linux and to \"Meta\" on macOS."},{"name":"force","type":"boolean","required":false,"description":"Whether to bypass the actionability checks. Defaults to `false`.","default":"false"},{"name":"scroll","type":"ScrollMode<\"auto\"|\"none\">","required":false,"description":"Controls whether Playwright scrolls the element into view before performing the action. Defaults to `\"auto\"`,\nwhich scrolls the element into view when necessary, including scrolling nested scrollable containers. When set to\n`\"none\"`, Playwright does not scroll the element and the action fails if the element is not already in the viewport.\nThis is useful to assert that an element is reachable by the user without additional scrolling.","default":"\"auto\""},{"name":"noWaitAfter","type":"boolean","required":false,"description":"Actions that initiate navigations are waiting for these navigations to happen and for pages to start loading. You can\nopt out of waiting via setting this flag. You would only need this option in the exceptional cases such as navigating\nto inaccessible pages. Defaults to `false`.","default":"false"},{"name":"timeout","type":"float","required":false,"description":"Maximum time in milliseconds. Defaults to `0` - no timeout. The default value can be changed via `actionTimeout` option in the config, or by using the `BrowserContext.setDefaultTimeout()` or\n`Page.setDefaultTimeout()` methods.","default":"0"},{"name":"signal","type":"AbortSignal","required":false,"description":"Allows to cancel the operation using an `AbortSignal`. If the signal is aborted, the operation will be aborted and throw an error.\nNote that providing a signal does not disable the default timeout, which can be changed using `BrowserContext.setDefaultTimeout()` or `Page.setDefaultTimeout()`; pass `timeout: 0` to disable the timeout entirely."},{"name":"trial","type":"boolean","required":false,"description":"When set, this method only performs the actionability checks and skips the action. Defaults to `false`. Useful to wait until the element is ready for the action without performing it. Note that keyboard `modifiers` will be pressed regardless of `trial` to allow testing elements which are only visible when those keys are pressed.","default":"false"},{"name":"steps","type":"int","required":false,"description":"Defaults to 1. Sends `n` interpolated `mousemove` events to represent travel between Playwright's current cursor position and the provided destination. When set to 1, emits a single `mousemove` event at the destination location.","default":"1"}]},
