  "Locator.drop": {"key":"Locator.drop","title":"locator.drop()","signature":"drop(payload: Object, options?: Object): Promise<void>","returns":"Promise<void>","since":"v1.60","docsUrl":"https://playwright.dev/docs/api/class-locator#locator-drop","params":[{"name":"payload","type":"Object","required":true,"description":"* alias: DropPayload\n  - `files` ?<[path]|[Array]<[path]>|[Object]|[Array]<[Object]>>\n    * alias: FilePayload\n    - `name` <[string]> File name\n    - `mimeType` <[string]> File type\n    - `buffer` <[Buffer]> File content\n  - `data` ?<[Object]<[string], [string]>>\n\nData to drop onto the target. Provide `files` (file paths or in-memory buffers), `data`\n(a mime-type → string map for clipboard-like content such as `text/plain`, `text/html`,\n`text/uri-list`), or both."},{"name":"options","type":"Object","required":false,"description":""}],"options":[{"name":"position","type":"Object","required":false,"description":"* alias: Position\n  - `x` <[float]>\n  - `y` <[float]>\n\nA point to use relative to the top-left corner of element padding box. If not specified, uses some visible point of the\nelement."},{"name":"timeout","type":"float","required":false,"description":"Maximum time in milliseconds. Defaults to `0` - no timeout. The default value can be changed via `actionTimeout` option in the config, or by using the `BrowserContext.setDefaultTimeout()` or\n`Page.setDefaultTimeout()` methods.","default":"0"},{"name":"signal","type":"AbortSignal","required":false,"description":"Allows to cancel the operation using an `AbortSignal`. If the signal is aborted, the operation will be aborted and throw an error.\nNote that providing a signal does not disable the default timeout, which can be changed using `BrowserContext.setDefaultTimeout()` or `Page.setDefaultTimeout()`; pass `timeout: 0` to disable the timeout entirely."}]},
