  "Locator.evaluate": {"key":"Locator.evaluate","title":"locator.evaluate()","signature":"evaluate(pageFunction: PageFunctionOn<E, Arg, R>, arg?: Arg, options?: Object): Promise<R>","returns":"Promise<R>","since":"v1.14","docsUrl":"https://playwright.dev/docs/api/class-locator#locator-evaluate","params":[{"name":"pageFunction","type":"PageFunctionOn<E, Arg, R>","required":true,"description":"Function to be evaluated in the page context."},{"name":"arg","type":"Arg","required":false,"description":"Optional argument to pass to `expression`."},{"name":"options","type":"{ timeout?: number, signal?: AbortSignal, exposeFunctions?: boolean }","required":false,"description":""}],"options":[{"name":"exposeFunctions","type":"boolean","required":false,"description":"When set to `true`, functions passed inside `arg` are exposed in the page and can be called from the page function. Calling one returns a [Promise] of its result. Under the hood, each function is exposed via `Page.exposeFunction()`, so it is technically accessible from all frames and worlds of the page. Exposed functions are cleared upon the top-level navigation. Defaults to `false`, in which case functions are not serializable and passing one throws an error.","default":"false"},{"name":"timeout","type":"float","required":false,"description":"Maximum time in milliseconds to wait for the locator before evaluating. Note that after locator is resolved, evaluation itself is not limited by the timeout. Defaults to `0` - no timeout.","default":"0"},{"name":"signal","type":"AbortSignal","required":false,"description":"Allows to cancel the operation using an `AbortSignal`. If the signal is aborted, the operation will be aborted and throw an error.\nNote that providing a signal does not disable the default timeout, which can be changed using `BrowserContext.setDefaultTimeout()` or `Page.setDefaultTimeout()`; pass `timeout: 0` to disable the timeout entirely."}]},
  "Locator.evaluateAll": {"key":"Locator.evaluateAll","title":"locator.evaluateAll()","signature":"evaluateAll(pageFunction: PageFunctionOn<E[], Arg, R>, arg?: Arg): Promise<R>","returns":"Promise<R>","since":"v1.14","docsUrl":"https://playwright.dev/docs/api/class-locator#locator-evaluate-all","params":[{"name":"pageFunction","type":"PageFunctionOn<E[], Arg, R>","required":true,"description":"Function to be evaluated in the page context."},{"name":"arg","type":"Arg","required":false,"description":"Optional argument to pass to `expression`."}],"options":[]},
  "Locator.evaluateHandle": {"key":"Locator.evaluateHandle","title":"locator.evaluateHandle()","signature":"evaluateHandle(pageFunction: PageFunctionOn<E, Arg, R>, arg?: Arg, options?: Object): Promise<SmartHandle<R>>","returns":"Promise<SmartHandle<R>>","since":"v1.14","docsUrl":"https://playwright.dev/docs/api/class-locator#locator-evaluate-handle","params":[{"name":"pageFunction","type":"PageFunctionOn<E, Arg, R>","required":true,"description":"Function to be evaluated in the page context."},{"name":"arg","type":"Arg","required":false,"description":"Optional argument to pass to `expression`."},{"name":"options","type":"{ timeout?: number, signal?: AbortSignal, exposeFunctions?: boolean }","required":false,"description":""}],"options":[{"name":"exposeFunctions","type":"boolean","required":false,"description":"When set to `true`, functions passed inside `arg` are exposed in the page and can be called from the page function. Calling one returns a [Promise] of its result. Under the hood, each function is exposed via `Page.exposeFunction()`, so it is technically accessible from all frames and worlds of the page. Exposed functions are cleared upon the top-level navigation. Defaults to `false`, in which case functions are not serializable and passing one throws an error.","default":"false"},{"name":"timeout","type":"float","required":false,"description":"Maximum time in milliseconds to wait for the locator before evaluating. Note that after locator is resolved, evaluation itself is not limited by the timeout. Defaults to `0` - no timeout.","default":"0"},{"name":"signal","type":"AbortSignal","required":false,"description":"Allows to cancel the operation using an `AbortSignal`. If the signal is aborted, the operation will be aborted and throw an error.\nNote that providing a signal does not disable the default timeout, which can be changed using `BrowserContext.setDefaultTimeout()` or `Page.setDefaultTimeout()`; pass `timeout: 0` to disable the timeout entirely."}]},
