  "Locator.filter": {"key":"Locator.filter","title":"locator.filter()","signature":"filter(options?: Object): Locator","returns":"Locator","since":"v1.22","docsUrl":"https://playwright.dev/docs/api/class-locator#locator-filter","params":[{"name":"options","type":"Object","required":false,"description":""}],"options":[{"name":"hasNot","type":"Locator","required":false,"description":"Matches elements that do not contain an element that matches an inner locator. Inner locator is queried against the outer one.\nFor example, `article` that does not have `div` matches `<article><span>Playwright</span></article>`.\n\nNote that outer and inner locators must belong to the same frame. Inner locator must not contain [FrameLocator]s."},{"name":"hasNotText","type":"string|RegExp","required":false,"description":"Matches elements that do not contain specified text somewhere inside, possibly in a child or a descendant element. When passed a [string], matching is case-insensitive and searches for a substring."},{"name":"visible","type":"boolean","required":false,"description":"Only matches visible or invisible elements.\n\n## locator-options-list-v1.14\n- %%-locator-option-has-text-%%\n- %%-locator-option-has-%%"}]},
