  "Page.addInitScript": {"key":"Page.addInitScript","title":"page.addInitScript()","signature":"addInitScript(script: PageFunction<Arg, any> | { path?: string, content?: string }, arg?: Arg, options?: { exposeFunctions?: boolean }): Promise<Disposable>","returns":"Promise<Disposable>","since":"v1.8","docsUrl":"https://playwright.dev/docs/api/class-page#page-add-init-script","params":[{"name":"script","type":"PageFunction<Arg, any> | { path?: string, content?: string }","required":true,"description":"- `path` ?<[path]> Path to the JavaScript file. If `path` is a relative path, then it is resolved relative to the\n    current working directory. Optional.\n  - `content` ?<[string]> Raw script content. Optional.\n\nScript to be evaluated in the page."},{"name":"arg","type":"Arg","required":false,"description":"Optional argument to pass to `script` (only supported when passing a function)."},{"name":"options","type":"{ exposeFunctions?: boolean }","required":false,"description":""}],"options":[{"name":"exposeFunctions","type":"boolean","required":false,"description":"When set to `true`, functions passed inside `arg` are exposed in the page and can be called from the init script. Calling one returns a [Promise] of its result. Under the hood, each function is exposed via `Page.exposeFunction()`, so it is technically accessible from all frames and worlds of the page. Unlike functions passed to `Page.evaluate()`, functions passed to an init script are exposed in every new document, so they survive navigations. Defaults to `false`, in which case functions are not serializable and are silently dropped.","default":"false"}]},
