  "Page.ariaSnapshot": {"key":"Page.ariaSnapshot","title":"page.ariaSnapshot()","signature":"ariaSnapshot(options?: Object): Promise<string>","returns":"Promise<string>","since":"v1.59","docsUrl":"https://playwright.dev/docs/api/class-page#page-aria-snapshot","params":[{"name":"options","type":"Object","required":false,"description":""}],"options":[{"name":"mode","type":"AriaSnapshotMode<\"ai\"|\"default\">","required":false,"description":"When set to `\"ai\"`, returns a snapshot optimized for AI consumption: including element references like `[ref=e2]` and snapshots of `<iframe>`s. Defaults to `\"default\"`.","default":"\"default\""},{"name":"timeout","type":"float","required":false,"description":"Maximum time in milliseconds. Defaults to `0` - no timeout. The default value can be changed via `actionTimeout` option in the config, or by using the `BrowserContext.setDefaultTimeout()` or\n`Page.setDefaultTimeout()` methods.","default":"0"},{"name":"signal","type":"AbortSignal","required":false,"description":"Allows to cancel the operation using an `AbortSignal`. If the signal is aborted, the operation will be aborted and throw an error.\nNote that providing a signal does not disable the default timeout, which can be changed using `BrowserContext.setDefaultTimeout()` or `Page.setDefaultTimeout()`; pass `timeout: 0` to disable the timeout entirely."},{"name":"depth","type":"int","required":false,"description":"When specified, limits the depth of the snapshot."},{"name":"boxes","type":"boolean","required":false,"description":"When `true`, appends each element's bounding box as `[box=x,y,width,height]` to the snapshot. Coordinates are\nrelative to the viewport, in CSS pixels, as returned by `Element.getBoundingClientRect()`.\nDefaults to `false`.","default":"false"}]},
