  "Page.evaluate": {"key":"Page.evaluate","title":"page.evaluate()","signature":"evaluate(pageFunction: PageFunction<Arg, R>, arg: Arg, options?: { exposeFunctions?: boolean }): Promise<R>","returns":"Promise<R>","since":"v1.8","docsUrl":"https://playwright.dev/docs/api/class-page#page-evaluate","params":[{"name":"pageFunction","type":"PageFunction<Arg, R>","required":true,"description":"Function to be evaluated in the page context."},{"name":"arg","type":"Arg","required":true,"description":"Optional argument to pass to `expression`."},{"name":"options","type":"{ exposeFunctions?: boolean }","required":false,"description":""}],"options":[{"name":"exposeFunctions","type":"boolean","required":false,"description":"When set to `true`, functions passed inside `arg` are exposed in the page and can be called from the page function. Calling one returns a [Promise] of its result. Under the hood, each function is exposed via `Page.exposeFunction()`, so it is technically accessible from all frames and worlds of the page. Exposed functions are cleared upon the top-level navigation. Defaults to `false`, in which case functions are not serializable and passing one throws an error.","default":"false"}]},
