  "Page.pdf": {"key":"Page.pdf","title":"page.pdf()","signature":"pdf(options?: Object): Promise<Buffer>","returns":"Promise<Buffer>","since":"v1.8","docsUrl":"https://playwright.dev/docs/api/class-page#page-pdf","params":[{"name":"options","type":"Object","required":false,"description":""}],"options":[{"name":"path","type":"path","required":false,"description":"The file path to save the PDF to. If `path` is a relative path, then it is resolved relative to the current\nworking directory. If no path is provided, the PDF won't be saved to the disk."},{"name":"scale","type":"float","required":false,"description":"Scale of the webpage rendering. Defaults to `1`. Scale amount must be between 0.1 and 2.","default":"1"},{"name":"displayHeaderFooter","type":"boolean","required":false,"description":"Display header and footer. Defaults to `false`.","default":"false"},{"name":"headerTemplate","type":"string","required":false,"description":"HTML template for the print header. Should be valid HTML markup with following classes used to inject printing values\ninto them:\n* `'date'` formatted print date\n* `'title'` document title\n* `'url'` document location\n* `'pageNumber'` current page number\n* `'totalPages'` total pages in the document"},{"name":"footerTemplate","type":"string","required":false,"description":"HTML template for the print footer. Should use the same format as the `headerTemplate`."},{"name":"printBackground","type":"boolean","required":false,"description":"Print background graphics. Defaults to `false`.","default":"false"},{"name":"landscape","type":"boolean","required":false,"description":"Paper orientation. Defaults to `false`.","default":"false"},{"name":"pageRanges","type":"string","required":false,"description":"Paper ranges to print, e.g., '1-5, 8, 11-13'. Defaults to the empty string, which means print all pages."},{"name":"format","type":"string","required":false,"description":"Paper format. If set, takes priority over `width` or `height` options. Defaults to 'Letter'."},{"name":"width","type":"string|float","required":false,"description":"Paper width, accepts values labeled with units."},{"name":"height","type":"string|float","required":false,"description":"Paper height, accepts values labeled with units."},{"name":"margin","type":"Object","required":false,"description":"- `top` ?<[string]|[float]> Top margin, accepts values labeled with units. Defaults to `0`.\n  - `right` ?<[string]|[float]> Right margin, accepts values labeled with units. Defaults to `0`.\n  - `bottom` ?<[string]|[float]> Bottom margin, accepts values labeled with units. Defaults to `0`.\n  - `left` ?<[string]|[float]> Left margin, accepts values labeled with units. Defaults to `0`.\n\nPaper margins, defaults to none.","default":"0"},{"name":"preferCSSPageSize","type":"boolean","required":false,"description":"Give any CSS `@page` size declared in the page priority over what is declared in `width` and\n`height` or `format` options. Defaults to `false`, which will scale the content to fit the paper\nsize.","default":"false"},{"name":"tagged","type":"boolean","required":false,"description":"Whether or not to generate tagged (accessible) PDF. Defaults to `false`.","default":"false"},{"name":"outline","type":"boolean","required":false,"description":"Whether or not to embed the document outline into the PDF. Defaults to `false`.","default":"false"}]},
