  "Page.press": {"key":"Page.press","title":"page.press()","signature":"press(selector: string, key: string, options?: Object): Promise<void>","returns":"Promise<void>","since":"v1.8","docsUrl":"https://playwright.dev/docs/api/class-page#page-press","params":[{"name":"selector","type":"string","required":true,"description":"A selector to search for an element. If there are multiple elements satisfying the selector, the first will be used."},{"name":"key","type":"string","required":true,"description":"Name of the key to press or a character to generate, such as `ArrowLeft` or `a`."},{"name":"options","type":"Object","required":false,"description":""}],"options":[{"name":"delay","type":"float","required":false,"description":"Time to wait between `keydown` and `keyup` in milliseconds. Defaults to 0.","default":"0"},{"name":"noWaitAfter","type":"boolean","required":false,"description":"Actions that initiate navigations are waiting for these navigations to happen and for pages to start loading. You can\nopt out of waiting via setting this flag. You would only need this option in the exceptional cases such as navigating\nto inaccessible pages. Defaults to `false`.","default":"false"},{"name":"strict","type":"boolean","required":false,"description":"When true, the call requires selector to resolve to a single element. If given selector resolves to more\nthan one element, the call throws an exception."},{"name":"timeout","type":"float","required":false,"description":"Maximum time in milliseconds. Defaults to `0` - no timeout. The default value can be changed via `actionTimeout` option in the config, or by using the `BrowserContext.setDefaultTimeout()` or\n`Page.setDefaultTimeout()` methods.","default":"0"},{"name":"signal","type":"AbortSignal","required":false,"description":"Allows to cancel the operation using an `AbortSignal`. If the signal is aborted, the operation will be aborted and throw an error.\nNote that providing a signal does not disable the default timeout, which can be changed using `BrowserContext.setDefaultTimeout()` or `Page.setDefaultTimeout()`; pass `timeout: 0` to disable the timeout entirely."}]},
