  "Page.reload": {"key":"Page.reload","title":"page.reload()","signature":"reload(options?: Object): Promise<null|Response>","returns":"Promise<null|Response>","since":"v1.8","docsUrl":"https://playwright.dev/docs/api/class-page#page-reload","params":[{"name":"options","type":"Object","required":false,"description":""}],"options":[{"name":"waitUntil","type":"WaitUntilState<\"load\"|\"domcontentloaded\"|\"networkidle\"|\"commit\">","required":false,"description":"When to consider operation succeeded, defaults to `load`. Events can be either:\n* `'domcontentloaded'` - consider operation to be finished when the `DOMContentLoaded` event is fired.\n* `'load'` - consider operation to be finished when the `load` event is fired.\n* `'networkidle'` - **DISCOURAGED** consider operation to be finished when there are no network connections for at least `500` ms. Don't use this method for testing, rely on web assertions to assess readiness instead.\n* `'commit'` - consider operation to be finished when network response is received and the document started loading.","default":"load"},{"name":"timeout","type":"float","required":false,"description":"Maximum operation time in milliseconds. Defaults to `0` - no timeout. The default value can be changed via `navigationTimeout` option in the config, or by using the `BrowserContext.setDefaultNavigationTimeout()`,\n`BrowserContext.setDefaultTimeout()`,\n`Page.setDefaultNavigationTimeout()` or\n`Page.setDefaultTimeout()` methods.","default":"0"},{"name":"signal","type":"AbortSignal","required":false,"description":"Allows to cancel the operation using an `AbortSignal`. If the signal is aborted, the operation will be aborted and throw an error.\nNote that providing a signal does not disable the default timeout, which can be changed using `BrowserContext.setDefaultTimeout()` or `Page.setDefaultTimeout()`; pass `timeout: 0` to disable the timeout entirely."}]},
  "Page.removeAllListeners": {"key":"Page.removeAllListeners","title":"page.removeAllListeners()","signature":"removeAllListeners(type?: string): this","returns":"this","since":"v1.47","docsUrl":"https://playwright.dev/docs/api/class-page#page-remove-all-listeners","params":[{"name":"type","type":"string","required":false,"description":""}],"options":[{"name":"behavior","type":"RemoveAllListenersBehavior<\"wait\"|\"ignoreErrors\"|\"default\">","required":false,"description":"Specifies whether to wait for already running listeners and what to do if they throw errors:\n* `'default'` - do not wait for current listener calls (if any) to finish, if the listener throws, it may result in unhandled error\n* `'wait'` - wait for current listener calls (if any) to finish\n* `'ignoreErrors'` - do not wait for current listener calls (if any) to finish, all errors thrown by the listeners after removal are silently caught"}]},
