  "Page.setInputFiles": {"key":"Page.setInputFiles","title":"page.setInputFiles()","signature":"setInputFiles(selector: string, files: string|ReadonlyArray<string>|{ /** * File name */ name: str…, options?: Object): Promise<void>","returns":"Promise<void>","since":"v1.8","docsUrl":"https://playwright.dev/docs/api/class-page#page-set-input-files","params":[{"name":"selector","type":"string","required":true,"description":"A selector to search for an element. If there are multiple elements satisfying the selector, the first will be used."},{"name":"files","type":"string|ReadonlyArray<string>|{ /** * File name */ name: string; /** * File type */ mimeType: string; /** * File content…","required":true,"description":"* alias: FilePayload\n  - `name` <[string]> File name\n  - `mimeType` <[string]> File type\n  - `buffer` <[Buffer]> File content"},{"name":"options","type":"Object","required":false,"description":""}],"options":[{"name":"noWaitAfter","type":"boolean","required":false,"description":"This option has no effect."},{"name":"strict","type":"boolean","required":false,"description":"When true, the call requires selector to resolve to a single element. If given selector resolves to more\nthan one element, the call throws an exception."},{"name":"timeout","type":"float","required":false,"description":"Maximum time in milliseconds. Defaults to `0` - no timeout. The default value can be changed via `actionTimeout` option in the config, or by using the `BrowserContext.setDefaultTimeout()` or\n`Page.setDefaultTimeout()` methods.","default":"0"},{"name":"signal","type":"AbortSignal","required":false,"description":"Allows to cancel the operation using an `AbortSignal`. If the signal is aborted, the operation will be aborted and throw an error.\nNote that providing a signal does not disable the default timeout, which can be changed using `BrowserContext.setDefaultTimeout()` or `Page.setDefaultTimeout()`; pass `timeout: 0` to disable the timeout entirely."}]},
  "Page.setViewportSize": {"key":"Page.setViewportSize","title":"page.setViewportSize()","signature":"setViewportSize(viewportSize: Object): Promise<void>","returns":"Promise<void>","since":"v1.8","docsUrl":"https://playwright.dev/docs/api/class-page#page-set-viewport-size","params":[{"name":"viewportSize","type":"{ /** * page width in pixels. */ width: number; /** * page height in pixels. */ height: number; }","required":true,"description":"- `width` <[int]> page width in pixels.\n  - `height` <[int]> page height in pixels."}],"options":[]},
  "Page.tap": {"key":"Page.tap","title":"page.tap()","signature":"tap(selector: string, options?: Object): Promise<void>","returns":"Promise<void>","since":"v1.8","docsUrl":"https://playwright.dev/docs/api/class-page#page-tap","params":[{"name":"selector","type":"string","required":true,"description":"A selector to search for an element. If there are multiple elements satisfying the selector, the first will be used."},{"name":"options","type":"Object","required":false,"description":""}],"options":[{"name":"force","type":"boolean","required":false,"description":"Whether to bypass the actionability checks. Defaults to `false`.","default":"false"},{"name":"scroll","type":"ScrollMode<\"auto\"|\"none\">","required":false,"description":"Controls whether Playwright scrolls the element into view before performing the action. Defaults to `\"auto\"`,\nwhich scrolls the element into view when necessary, including scrolling nested scrollable containers. When set to\n`\"none\"`, Playwright does not scroll the element and the action fails if the element is not already in the viewport.\nThis is useful to assert that an element is reachable by the user without additional scrolling.","default":"\"auto\""},{"name":"modifiers","type":"Array<KeyboardModifier<\"Alt\"|\"Control\"|\"ControlOrMeta\"|\"Meta\"|\"Shift\">>","required":false,"description":"Modifier keys to press. Ensures that only these modifiers are pressed during the operation, and then restores current\nmodifiers back. If not specified, currently pressed modifiers are used. \"ControlOrMeta\" resolves to \"Control\" on Windows\nand Linux and to \"Meta\" on macOS."},{"name":"noWaitAfter","type":"boolean","required":false,"description":"This option has no effect."},{"name":"position","type":"Object","required":false,"description":"* alias: Position\n  - `x` <[float]>\n  - `y` <[float]>\n\nA point to use relative to the top-left corner of element padding box. If not specified, uses some visible point of the\nelement."},{"name":"strict","type":"boolean","required":false,"description":"When true, the call requires selector to resolve to a single element. If given selector resolves to more\nthan one element, the call throws an exception."},{"name":"timeout","type":"float","required":false,"description":"Maximum time in milliseconds. Defaults to `0` - no timeout. The default value can be changed via `actionTimeout` option in the config, or by using the `BrowserContext.setDefaultTimeout()` or\n`Page.setDefaultTimeout()` methods.","default":"0"},{"name":"signal","type":"AbortSignal","required":false,"description":"Allows to cancel the operation using an `AbortSignal`. If the signal is aborted, the operation will be aborted and throw an error.\nNote that providing a signal does not disable the default timeout, which can be changed using `BrowserContext.setDefaultTimeout()` or `Page.setDefaultTimeout()`; pass `timeout: 0` to disable the timeout entirely."},{"name":"trial","type":"boolean","required":false,"description":"When set, this method only performs the actionability checks and skips the action. Defaults to `false`. Useful to wait until the element is ready for the action without performing it. Note that keyboard `modifiers` will be pressed regardless of `trial` to allow testing elements which are only visible when those keys are pressed.","default":"false"}]},
