  "Page.unroute": {"key":"Page.unroute","title":"page.unroute()","signature":"unroute(url: string|RegExp|URLPattern|((url: URL) => boolean), handler?: ((route: Route, request: Request) => Promise<any>|any)): Promise<void>","returns":"Promise<void>","since":"v1.8","docsUrl":"https://playwright.dev/docs/api/class-page#page-unroute","params":[{"name":"url","type":"string|RegExp|URLPattern|((url: URL) => boolean)","required":true,"description":"A glob pattern, regex pattern, URL pattern, or predicate receiving [URL] to match while routing."},{"name":"handler","type":"((route: Route, request: Request) => Promise<any>|any)","required":false,"description":"Optional handler function to route the request."}],"options":[]},
  "Page.unrouteAll": {"key":"Page.unrouteAll","title":"page.unrouteAll()","signature":"unrouteAll(options?: Object): Promise<void>","returns":"Promise<void>","since":"v1.41","docsUrl":"https://playwright.dev/docs/api/class-page#page-unroute-all","params":[{"name":"options","type":"Object","required":false,"description":""}],"options":[{"name":"behavior","type":"UnrouteBehavior<\"wait\"|\"ignoreErrors\"|\"default\">","required":false,"description":"Specifies whether to wait for already running handlers and what to do if they throw errors:\n* `'default'` - do not wait for current handler calls (if any) to finish, if unrouted handler throws, it may result in unhandled error\n* `'wait'` - wait for current handler calls (if any) to finish\n* `'ignoreErrors'` - do not wait for current handler calls (if any) to finish, all errors thrown by the handlers after unrouting are silently caught"}]},
