  "PageAssertions.not": {"key":"PageAssertions.not","title":"pageAssertions.not","signature":"not: PageAssertions","returns":"PageAssertions","since":"v1.20","docsUrl":"https://playwright.dev/docs/api/class-pageassertions#page-assertions-not","params":[],"options":[]},
  "PageAssertions.toHaveScreenshot#1": {"key":"PageAssertions.toHaveScreenshot#1","title":"pageAssertions.toHaveScreenshot#1()","signature":"toHaveScreenshot#1(): void","since":"v1.23","docsUrl":"https://playwright.dev/docs/api/class-pageassertions#page-assertions-to-have-screenshot#1","params":[{"name":"name","type":"string|Array<string>","required":true,"description":"Snapshot name. Must have a `.png` or `.webp` extension, the screenshot is captured in the corresponding format. Both formats are lossless."}],"options":[{"name":"timeout","type":"float","required":false,"description":"Time to retry the assertion for in milliseconds. Defaults to `timeout` in `TestConfig.expect`.","default":"timeout"},{"name":"signal","type":"AbortSignal","required":false,"description":"An optional `AbortSignal` that\ncan cancel the assertion. Aborting the signal fails the assertion like a timeout: if the signal\nis aborted while the assertion is retrying, or is already aborted before the assertion starts,\nthe assertion fails without retrying further."},{"name":"animations","type":"ScreenshotAnimations<\"disabled\"|\"allow\">","required":false,"description":"When set to `\"disabled\"`, stops CSS animations, CSS transitions and Web Animations. Animations get different treatment depending on their duration:\n* finite animations are fast-forwarded to completion, so they'll fire `transitionend` event.\n* infinite animations are canceled to initial state, and then played over after the screenshot.\n\nDefaults to `\"disabled\"` that disables animations.","default":"\"disabled\""},{"name":"caret","type":"ScreenshotCaret<\"hide\"|\"initial\">","required":false,"description":"When set to `\"hide\"`, screenshot will hide text caret. When set to `\"initial\"`, text caret behavior will not be changed.  Defaults to `\"hide\"`.","default":"\"hide\""},{"name":"clip","type":"Object","required":false,"description":"* alias-java: Clip\n  - `x` <[float]> x-coordinate of top-left corner of clip area\n  - `y` <[float]> y-coordinate of top-left corner of clip area\n  - `width` <[float]> width of clipping area\n  - `height` <[float]> height of clipping area\n\nAn object which specifies clipping of the resulting image."},{"name":"fullPage","type":"boolean","required":false,"description":"When true, takes a screenshot of the full scrollable page, instead of the currently visible viewport. Defaults to\n`false`."},{"name":"mask","type":"Array<Locator>","required":false,"description":"Specify locators that should be masked when the screenshot is taken. Masked elements will be overlaid with\na pink box `#FF00FF` (customized by `maskColor`) that completely covers its bounding box.\nThe mask is also applied to invisible elements, see Matching only visible elements to disable that."},{"name":"maskColor","type":"string","required":false,"description":"Specify the color of the overlay box for masked elements, in CSS color format. Default color is pink `#FF00FF`."},{"name":"stylePath","type":"string|Array<string>","required":false,"description":"File name containing the stylesheet to apply while making the screenshot. This is where you can hide dynamic elements, make elements invisible or change their properties to help you creating repeatable screenshots. This stylesheet pierces the Shadow DOM and applies to the inner frames.\n\n## screenshot-options-common-list-v1.8\n- %%-screenshot-option-animations-%%\n- %%-screenshot-option-omit-background-%%\n- %%-screenshot-option-quality-%%\n- %%-screenshot-option-path-%%\n- %%-screenshot-option-scale-%%\n- %%-screenshot-option-caret-%%\n- %%-screenshot-option-type-%%\n- %%-screenshot-option-mask-%%"},{"name":"omitBackground","type":"boolean","required":false,"description":"Hides default white background and allows capturing screenshots with transparency. Not applicable to `jpeg` images.\nDefaults to `false`.","default":"false"},{"name":"scale","type":"ScreenshotScale<\"css\"|\"device\">","required":false,"description":"When set to `\"css\"`, screenshot will have a single pixel per each css pixel on the page. For high-dpi devices, this will keep screenshots small. Using `\"device\"` option will produce a single pixel per each device pixel, so screenshots of high-dpi devices will be twice as large or even larger.\n\nDefaults to `\"css\"`.","default":"\"css\""},{"name":"maxDiffPixels","type":"int","required":false,"description":"An acceptable amount of pixels that could be different. Default is configurable with `TestConfig.expect`. Unset by default."},{"name":"maxDiffPixelRatio","type":"float","required":false,"description":"An acceptable ratio of pixels that are different to the total amount of pixels, between `0` and `1`. Default is configurable with `TestConfig.expect`. Unset by default."},{"name":"threshold","type":"float","required":false,"description":"An acceptable perceived color difference in the YIQ color space\nbetween the same pixel in compared images, between zero (strict) and one (lax), default is configurable with\n`TestConfig.expect`. Defaults to `0.2`.\n\n## shared-context-params-list-v1.8\n- %%-context-option-acceptdownloads-%%\n- %%-context-option-ignorehttpserrors-%%\n- %%-context-option-bypasscsp-%%\n- %%-context-option-baseURL-%%\n- %%-context-option-viewport-%%\n- %%-csharp-context-option-viewport-%%\n- %%-python-context-option-viewport-%%\n- %%-context-option-screen-%%\n- %%-python-context-option-no-viewport-%%\n- %%-context-option-useragent-%%\n- %%-context-option-devicescalefactor-%%\n- %%-context-option-ismobile-%%\n- %%-context-option-hastouch-%%\n- %%-context-option-javascriptenabled-%%\n- %%-context-option-timezoneid-%%\n- %%-context-option-geolocation-%%\n- %%-context-option-locale-%%\n- %%-context-option-permissions-%%\n- %%-context-option-extrahttpheaders-%%\n- %%-context-option-offline-%%\n- %%-context-option-httpcredentials-%%\n- %%-context-option-colorscheme-%%\n- %%-context-option-colorscheme-csharp-python-%%\n- %%-context-option-reducedMotion-%%\n- %%-context-option-reducedMotion-csharp-python-%%\n- %%-context-option-forcedColors-%%\n- %%-context-option-forcedColors-csharp-python-%%\n- %%-context-option-contrast-%%\n- %%-context-option-contrast-csharp-python-%%\n- %%-context-option-logger-%%\n- %%-context-option-recordhar-%%\n- %%-context-option-recordhar-path-%%\n- %%-context-option-recordhar-omit-content-%%\n- %%-context-option-recordhar-content-%%\n- %%-context-option-recordhar-mode-%%\n- %%-context-option-recordhar-url-filter-%%\n- %%-context-option-recordvideo-%%\n- %%-context-option-recordvideo-dir-%%\n- %%-context-option-recordvideo-size-%%\n- %%-context-option-strict-%%\n- %%-context-option-service-worker-policy-%%","default":"0.2"}]},
