  "Route.abort": {"key":"Route.abort","title":"route.abort()","signature":"abort(errorCode?: string): Promise<void>","returns":"Promise<void>","since":"v1.8","docsUrl":"https://playwright.dev/docs/api/class-route#route-abort","params":[{"name":"errorCode","type":"string","required":false,"description":"Optional error code. Defaults to `failed`, could be one of the following:\n* `'aborted'` - An operation was aborted (due to user action)\n* `'accessdenied'` - Permission to access a resource, other than the network, was denied\n* `'addressunreachable'` - The IP address is unreachable. This usually means that there is no route to the specified\n  host or network.\n* `'blockedbyclient'` - The client chose to block the request.\n* `'blockedbyresponse'` - The request failed because the response was delivered along with requirements which are not\n  met ('X-Frame-Options' and 'Content-Security-Policy' ancestor checks, for instance).\n* `'connectionaborted'` - A connection timed out as a result of not receiving an ACK for data sent.\n* `'connectionclosed'` - A connection was closed (corresponding to a TCP FIN).\n* `'connectionfailed'` - A connection attempt failed.\n* `'connectionrefused'` - A connection attempt was refused.\n* `'connectionreset'` - A connection was reset (corresponding to a TCP RST).\n* `'internetdisconnected'` - The Internet connection has been lost.\n* `'namenotresolved'` - The host name could not be resolved.\n* `'timedout'` - An operation timed out.\n* `'failed'` - A generic failure occurred.","default":"failed"}],"options":[]},
  "Route.continue": {"key":"Route.continue","title":"route.continue()","signature":"continue(options?: Object): Promise<void>","returns":"Promise<void>","since":"v1.8","docsUrl":"https://playwright.dev/docs/api/class-route#route-continue","params":[{"name":"options","type":"Object","required":false,"description":""}],"options":[{"name":"url","type":"string","required":false,"description":"If set changes the request URL. New URL must have same protocol as original one."},{"name":"method","type":"string","required":false,"description":"If set changes the request method (e.g. GET or POST)."},{"name":"postData","type":"string|Buffer|Serializable","required":false,"description":"If set changes the post data of request."},{"name":"headers","type":"Object<string, string>","required":false,"description":"If set changes the request HTTP headers. Header values will be converted to a string."}]},
  "Route.fallback": {"key":"Route.fallback","title":"route.fallback()","signature":"fallback(options?: Object): Promise<void>","returns":"Promise<void>","since":"v1.23","docsUrl":"https://playwright.dev/docs/api/class-route#route-fallback","params":[{"name":"options","type":"Object","required":false,"description":""}],"options":[{"name":"url","type":"string","required":false,"description":"If set changes the request URL. New URL must have same protocol as original one. Changing the URL won't\naffect the route matching, all the routes are matched using the original request URL."},{"name":"method","type":"string","required":false,"description":"If set changes the request method (e.g. GET or POST)."},{"name":"postData","type":"string|Buffer|Serializable","required":false,"description":"If set changes the post data of request."},{"name":"headers","type":"Object<string, string>","required":false,"description":"If set changes the request HTTP headers. Header values will be converted to a string."}]},
  "Route.fetch": {"key":"Route.fetch","title":"route.fetch()","signature":"fetch(options?: Object): Promise<APIResponse>","returns":"Promise<APIResponse>","since":"v1.29","docsUrl":"https://playwright.dev/docs/api/class-route#route-fetch","params":[{"name":"options","type":"Object","required":false,"description":""}],"options":[{"name":"url","type":"string","required":false,"description":"If set changes the request URL. New URL must have same protocol as original one."},{"name":"maxRedirects","type":"int","required":false,"description":"Maximum number of request redirects that will be followed automatically. An error will be thrown if the number is exceeded.\nDefaults to `20`. Pass `0` to not follow redirects.","default":"20"},{"name":"maxRetries","type":"int","required":false,"description":"Maximum number of times network errors should be retried. Currently only `ECONNRESET` error is retried. Does not retry based on HTTP response codes. An error will be thrown if the limit is exceeded. Defaults to `0` - no retries.","default":"0"},{"name":"timeout","type":"float","required":false,"description":"Request timeout in milliseconds. Defaults to `30000` (30 seconds). Pass `0` to disable timeout.","default":"30000"},{"name":"signal","type":"AbortSignal","required":false,"description":"Allows to cancel the operation using an `AbortSignal`. If the signal is aborted, the operation will be aborted and throw an error.\nNote that providing a signal does not disable the default timeout, which can be changed using `BrowserContext.setDefaultTimeout()` or `Page.setDefaultTimeout()`; pass `timeout: 0` to disable the timeout entirely."},{"name":"method","type":"string","required":false,"description":"If set changes the request method (e.g. GET or POST)."},{"name":"postData","type":"string|Buffer|Serializable","required":false,"description":"Allows to set post data of the request. If the data parameter is an object, it will be serialized to json string\nand `content-type` header will be set to `application/json` if not explicitly set. Otherwise the `content-type` header will be\nset to `application/octet-stream` if not explicitly set."},{"name":"headers","type":"Object<string, string>","required":false,"description":"If set changes the request HTTP headers. Header values will be converted to a string."}]},
  "Route.fulfill": {"key":"Route.fulfill","title":"route.fulfill()","signature":"fulfill(options?: Object): Promise<void>","returns":"Promise<void>","since":"v1.8","docsUrl":"https://playwright.dev/docs/api/class-route#route-fulfill","params":[{"name":"options","type":"Object","required":false,"description":""}],"options":[{"name":"status","type":"int","required":false,"description":"Response status code, defaults to `200`.","default":"200"},{"name":"headers","type":"Object<string, string>","required":false,"description":"Response headers. Header values will be converted to a string."},{"name":"contentType","type":"string","required":false,"description":"If set, equals to setting `Content-Type` response header."},{"name":"body","type":"string|Buffer","required":false,"description":"Response body."},{"name":"json","type":"Serializable","required":false,"description":"JSON response. This method will set the content type to `application/json` if not set."},{"name":"path","type":"path","required":false,"description":"File path to respond with. The content type will be inferred from file extension. If `path` is a relative path, then it\nis resolved relative to the current working directory."},{"name":"response","type":"APIResponse","required":false,"description":"[APIResponse] to fulfill route's request with. Individual fields of the response (such as headers) can be overridden using fulfill options."}]},
