  "Screencast.showActions": {"key":"Screencast.showActions","title":"screencast.showActions()","signature":"showActions(options?: Object): Promise<Disposable>","returns":"Promise<Disposable>","since":"v1.59","docsUrl":"https://playwright.dev/docs/api/class-screencast#screencast-show-actions","params":[{"name":"options","type":"Object","required":false,"description":""}],"options":[{"name":"duration","type":"unknown","required":false,"description":"How long each annotation is displayed in milliseconds. Defaults to `500`.","default":"500"},{"name":"position","type":"unknown","required":false,"description":"Position of the action title overlay. Defaults to `\"top-right\"`.","default":"\"top-right\""},{"name":"fontSize","type":"unknown","required":false,"description":"Font size of the action title in pixels. Defaults to `24`.","default":"24"},{"name":"cursor","type":"unknown","required":false,"description":"Cursor decoration shown for pointer actions. `\"pointer\"` (the default) renders\na mouse pointer that animates from the previous action point to the next one.\n`\"none\"` disables the cursor decoration."}]},
  "Screencast.showChapter": {"key":"Screencast.showChapter","title":"screencast.showChapter()","signature":"showChapter(title: string, options?: Object): Promise<void>","returns":"Promise<void>","since":"v1.59","docsUrl":"https://playwright.dev/docs/api/class-screencast#screencast-show-chapter","params":[{"name":"title","type":"string","required":true,"description":"Title text displayed prominently in the overlay."},{"name":"options","type":"Object","required":false,"description":""}],"options":[{"name":"description","type":"string","required":false,"description":"Optional description text displayed below the title."},{"name":"duration","type":"float","required":false,"description":"Duration in milliseconds after which the overlay is automatically removed. Defaults to `2000`.","default":"2000"}]},
  "Screencast.showOverlay": {"key":"Screencast.showOverlay","title":"screencast.showOverlay()","signature":"showOverlay(html: string, options?: Object): Promise<Disposable>","returns":"Promise<Disposable>","since":"v1.59","docsUrl":"https://playwright.dev/docs/api/class-screencast#screencast-show-overlay","params":[{"name":"html","type":"string","required":true,"description":"HTML content for the overlay."},{"name":"options","type":"Object","required":false,"description":""}],"options":[{"name":"duration","type":"float","required":false,"description":"Duration in milliseconds after which the overlay is automatically removed. Overlay stays until dismissed if not provided."}]},
  "Screencast.showOverlays": {"key":"Screencast.showOverlays","title":"screencast.showOverlays()","signature":"showOverlays(): Promise<void>","returns":"Promise<void>","since":"v1.59","docsUrl":"https://playwright.dev/docs/api/class-screencast#screencast-show-overlays","params":[],"options":[]},
  "Screencast.start": {"key":"Screencast.start","title":"screencast.start()","signature":"start(options?: Object): Promise<Disposable>","returns":"Promise<Disposable>","since":"v1.59","docsUrl":"https://playwright.dev/docs/api/class-screencast#screencast-start","params":[{"name":"options","type":"Object","required":false,"description":""}],"options":[{"name":"onFrame","type":"function\\(Object\\): Promise","required":false,"description":"* alias: ScreencastFrame\n  - `data` <[Buffer]> JPEG-encoded frame data.\n  - `timestamp` <[float]> The timestamp of when the frame was presented by the browser, in milliseconds since the Unix epoch.\n  - `viewportWidth` <[int]> Width of the page viewport at the time the frame was captured.\n  - `viewportHeight` <[int]> Height of the page viewport at the time the frame was captured.\n\nCallback that receives JPEG-encoded frame data along with the page viewport size at the time of capture."},{"name":"path","type":"path","required":false,"description":"Path where the video should be saved when the screencast is stopped. When provided, video recording is started."},{"name":"quality","type":"int","required":false,"description":"The quality of the image, between 0-100."},{"name":"size","type":"unknown","required":false,"description":"* alias-csharp: ScreencastSize\n  - `width` <[int]> Max frame width in pixels.\n  - `height` <[int]> Max frame height in pixels.\n\nSpecifies the dimensions of screencast frames. The actual frame is scaled to preserve the page's aspect ratio and may be smaller than these bounds.\nIf a screencast is already active (e.g. started by tracing or video recording), the existing configuration takes precedence and the frame size may exceed these bounds or this option may be ignored.\nIf not specified the size will be equal to page viewport scaled down to fit into 800×800."}]},
