  "TestStepInfo.attach": {"key":"TestStepInfo.attach","title":"testStepInfo.attach()","signature":"attach(name: string, options?: Object): Promise<void>","returns":"Promise<void>","since":"v1.51","docsUrl":"https://playwright.dev/docs/api/class-teststepinfo#test-step-info-attach","params":[{"name":"name","type":"string","required":true,"description":"Attachment name. The name will also be sanitized and used as the prefix of file name\nwhen saving to disk."},{"name":"options","type":"Object","required":false,"description":""}],"options":[{"name":"body","type":"string|Buffer","required":false,"description":"Attachment body. Mutually exclusive with `path`."},{"name":"contentType","type":"string","required":false,"description":"Content type of this attachment to properly present in the report, for example `'application/json'` or `'image/png'`. If omitted, content type is inferred based on the `path`, or defaults to `text/plain` for [string] attachments and `application/octet-stream` for [Buffer] attachments.","default":"text/plain"},{"name":"path","type":"string","required":false,"description":"Path on the filesystem to the attached file. Mutually exclusive with `body`."}]},
