  "Tracing.group": {"key":"Tracing.group","title":"tracing.group()","signature":"group(name: string, options?: Object): Promise<Disposable>","returns":"Promise<Disposable>","since":"v1.49","docsUrl":"https://playwright.dev/docs/api/class-tracing#tracing-group","params":[{"name":"name","type":"string","required":true,"description":"Group name shown in the trace viewer."},{"name":"options","type":"Object","required":false,"description":""}],"options":[{"name":"location","type":"unknown","required":false,"description":"* alias: Location\n  - `file` <[string]>\n  - `line` ?<[int]>\n  - `column` ?<[int]>\n\nSpecifies a custom location for the group to be shown in the trace viewer. Defaults to the location of the `Tracing.group()` call."}]},
