  "Tracing.start": {"key":"Tracing.start","title":"tracing.start()","signature":"start(options?: Object): Promise<void>","returns":"Promise<void>","since":"v1.12","docsUrl":"https://playwright.dev/docs/api/class-tracing#tracing-start","params":[{"name":"options","type":"Object","required":false,"description":""}],"options":[{"name":"name","type":"string","required":false,"description":"If specified, intermediate trace files are going to be saved into the files with the\ngiven name prefix inside the `BrowserType.launch.tracesDir` directory specified in `BrowserType.launch()`.\nTo specify the final trace zip file name, you need to pass `path` option to\n`Tracing.stop()` instead."},{"name":"screenshots","type":"boolean","required":false,"description":"Whether to capture screenshots during tracing. Screenshots are used to build\na timeline preview."},{"name":"snapshots","type":"boolean","required":false,"description":"If this option is true tracing will\n* capture DOM snapshot on every action\n* record network activity"},{"name":"sources","type":"boolean","required":false,"description":"Whether to include source files for trace actions."},{"name":"title","type":"string","required":false,"description":"Trace name to be shown in the Trace Viewer."},{"name":"live","type":"boolean","required":false,"description":"When enabled, the trace is written to an unarchived file that is updated in real time as actions occur,\ninstead of caching changes and archiving them into a zip file at the end. This is useful for live trace\nviewing during test execution."}]},
  "Tracing.startChunk": {"key":"Tracing.startChunk","title":"tracing.startChunk()","signature":"startChunk(options?: Object): Promise<void>","returns":"Promise<void>","since":"v1.15","docsUrl":"https://playwright.dev/docs/api/class-tracing#tracing-start-chunk","params":[{"name":"options","type":"Object","required":false,"description":""}],"options":[{"name":"title","type":"string","required":false,"description":"Trace name to be shown in the Trace Viewer."},{"name":"name","type":"string","required":false,"description":"If specified, intermediate trace files are going to be saved into the files with the\ngiven name prefix inside the `BrowserType.launch.tracesDir` directory specified in `BrowserType.launch()`.\nTo specify the final trace zip file name, you need to pass `path` option to\n`Tracing.stopChunk()` instead."}]},
  "Tracing.startHar": {"key":"Tracing.startHar","title":"tracing.startHar()","signature":"startHar(path: string, options?: Object): Promise<Disposable>","returns":"Promise<Disposable>","since":"v1.60","docsUrl":"https://playwright.dev/docs/api/class-tracing#tracing-start-har","params":[{"name":"path","type":"string","required":true,"description":"Path on the filesystem to write the HAR file to. If the file name ends with `.zip`, the HAR is saved as a zip archive with response bodies attached as separate files."},{"name":"options","type":"Object","required":false,"description":""}],"options":[{"name":"content","type":"HarContentPolicy<\"omit\"|\"embed\"|\"attach\">","required":false,"description":"Optional setting to control resource content management. If `omit` is specified, content is not persisted. If `attach` is specified, resources are persisted as separate files or entries in the ZIP archive. If `embed` is specified, content is stored inline the HAR file as per HAR specification. Defaults to `attach` for `.zip` output files and to `embed` for all other file extensions.","default":"attach"},{"name":"mode","type":"HarMode<\"full\"|\"minimal\">","required":false,"description":"When set to `minimal`, only record information necessary for routing from HAR. This omits sizes, timing, page, cookies, security and other types of HAR information that are not used when replaying from HAR. Defaults to `full`.","default":"full"},{"name":"urlFilter","type":"string|RegExp","required":false,"description":"A glob or regex pattern to filter requests that are stored in the HAR. Defaults to none."},{"name":"resourcesDir","type":"path","required":false,"description":"Only used together with `content: 'attach'`. When set, response bodies are placed in this directory instead of next to\nthe HAR file. Not compatible with a `.zip` HAR file."}]},
